//! Committed reference values, generated by independent SciPy 1.18.1 and
//! NumPy 2.5.4. The generator and input fixture remain in tests/scipy.
use orthogonal::*;

fn coeff(name: &str, n: usize, a: f64, b: f64, monic: bool) -> Vec<f64> {
    match name {
        "jacobi" => jacobi(n, a, b, monic),
        "legendre" => legendre(n, monic),
        "gegenbauer" => gegenbauer(n, a, monic),
        "genlaguerre" => genlaguerre(n, a, monic),
        "laguerre" => laguerre(n, monic),
        "hermite" => hermite(n, monic),
        "hermitenorm" => hermitenorm(n, monic),
        "chebyt" => chebyt(n, monic),
        "chebyu" => chebyu(n, monic),
        "chebyc" => chebyc(n, monic),
        "chebys" => chebys(n, monic),
        "sh_chebyt" => sh_chebyt(n, monic),
        "sh_chebyu" => sh_chebyu(n, monic),
        "sh_legendre" => sh_legendre(n, monic),
        "sh_jacobi" => sh_jacobi(n, a, b, monic),
        _ => panic!("unknown family {name}"),
    }
    .unwrap()
}

fn roots(name: &str, n: usize, a: f64, b: f64) -> Vec<f64> {
    let (nodes, weights) = match name {
        "jacobi" => roots_jacobi(n, a, b),
        "legendre" => roots_legendre(n),
        "gegenbauer" => roots_gegenbauer(n, a),
        "genlaguerre" => roots_genlaguerre(n, a),
        "laguerre" => roots_laguerre(n),
        "hermite" => roots_hermite(n),
        "hermitenorm" => roots_hermitenorm(n),
        "chebyt" => roots_chebyt(n),
        "chebyu" => roots_chebyu(n),
        "chebyc" => roots_chebyc(n),
        "chebys" => roots_chebys(n),
        "sh_chebyt" => roots_sh_chebyt(n),
        "sh_chebyu" => roots_sh_chebyu(n),
        "sh_legendre" => roots_sh_legendre(n),
        "sh_jacobi" => roots_sh_jacobi(n, a, b),
        _ => panic!("unknown family {name}"),
    }
    .unwrap();
    assert!(
        nodes.windows(2).all(|w| w[0] < w[1]),
        "{name}, n={n}: node ordering"
    );
    assert!(
        weights.iter().all(|w| *w >= 0.0 && w.is_finite()),
        "{name}, n={n}: weights"
    );
    nodes.into_iter().chain(weights).collect()
}

fn eval(name: &str, n: i32, a: f64, b: f64, x: f64) -> f64 {
    match name {
        "jacobi" => eval_jacobi(n, a, b, x),
        "legendre" => eval_legendre(n, x),
        "gegenbauer" => eval_gegenbauer(n, a, x),
        "genlaguerre" => eval_genlaguerre(n, a, x),
        "laguerre" => eval_laguerre(n, x),
        "hermite" => eval_hermite(n, x),
        "hermitenorm" => eval_hermitenorm(n, x),
        "chebyt" => eval_chebyt(n, x),
        "chebyu" => eval_chebyu(n, x),
        "chebyc" => eval_chebyc(n, x),
        "chebys" => eval_chebys(n, x),
        "sh_chebyt" => eval_sh_chebyt(n, x),
        "sh_chebyu" => eval_sh_chebyu(n, x),
        "sh_legendre" => eval_sh_legendre(n, x),
        "sh_jacobi" => eval_sh_jacobi(n, a, b, x),
        _ => panic!("unknown family {name}"),
    }
}

#[test]
fn all_saved_scipy_reference_values() {
    let cases = include_str!("fixtures/inputs.csv");
    let refs = include_str!("fixtures/expected.csv");
    let mut count = 0;
    for (input, expected) in cases.lines().skip(1).zip(refs.lines().skip(1)) {
        let fields: Vec<_> = input.split(',').collect();
        let answer: Vec<_> = expected.splitn(2, ',').collect();
        assert_eq!(fields[0], answer[0]);
        let n_i32: i32 = fields[3].parse().unwrap();
        let n: usize = n_i32.max(0) as usize;
        let a: f64 = fields[4].parse().unwrap();
        let b: f64 = fields[5].parse().unwrap();
        let x: f64 = fields[6].parse().unwrap();
        let monic = fields[7] == "1";
        let values = match fields[1] {
            "coeff" => coeff(fields[2], n, a, b, monic),
            "roots" => roots(fields[2], n, a, b),
            "eval" => vec![eval(fields[2], n as i32, a, b, x)],
            "assoc" => vec![assoc_legendre_p(n as i32, a as i32, x).unwrap()],
            "spherical" => vec![sph_legendre_p(n as i32, a as i32, x).unwrap()],
            "q" => {
                let (v, d) = lqn(n, x).unwrap();
                v.into_iter().chain(d).collect()
            }
            "assoc_q" => {
                let (v, d) = lqmn(a as usize, n, x).unwrap();
                v.into_iter().chain(d).flatten().collect()
            }
            "lpmv" => vec![lpmv(n_i32, a, x)],
            other => panic!("unknown kind {other}"),
        };
        let reference: Vec<f64> = answer[1]
            .split(';')
            .map(|v| v.parse::<f64>().unwrap())
            .collect();
        assert_eq!(
            values.len(),
            reference.len(),
            "case {}, {}",
            fields[0],
            fields[2]
        );
        for (i, (actual, expected)) in values.into_iter().zip(reference).enumerate() {
            let relative = match fields[1] {
                "roots" => 6e-9,
                "coeff" => 4e-9,
                _ => 3e-9,
            };
            let absolute = match fields[1] {
                "roots" => 5e-12,
                "coeff"
                    if matches!(
                        fields[2],
                        "legendre"
                            | "gegenbauer"
                            | "hermite"
                            | "hermitenorm"
                            | "chebyt"
                            | "chebyu"
                            | "chebyc"
                            | "chebys"
                    ) && i % 2 == 1 =>
                {
                    1e-8
                } // SciPy poly1d yields tiny parity-forbidden coefficients for H_12.
                _ => 2e-11,
            };
            let tolerance = absolute + relative * expected.abs();
            assert!(
                actual.is_finite() && (actual - expected).abs() <= tolerance,
                "case {} {} {} n={} index {}: actual={:e} expected={:e} tol={:e}",
                fields[0],
                fields[1],
                fields[2],
                n,
                i,
                actual,
                expected,
                tolerance
            );
        }
        count += 1;
    }
    assert_eq!(count, 1635);
}

#[test]
fn gauss_legendre_integrates_moments() {
    for n in [1, 2, 3, 8, 32, 128, 256] {
        let (nodes, weights) = roots_legendre(n).unwrap();
        for degree in 0..=12.min(2 * n - 1) {
            let integral: f64 = nodes
                .iter()
                .zip(&weights)
                .map(|(x, w)| w * x.powi(degree as i32))
                .sum();
            let expected = if degree % 2 == 1 {
                0.0
            } else {
                2.0 / (degree + 1) as f64
            };
            assert!(
                (integral - expected).abs() < 2e-12,
                "n={n}, degree={degree}: {integral}"
            );
        }
    }
}

#[test]
fn legendre_and_associated_table_entries_match_scalar_evaluators() {
    for &x in &[-1.0, -0.7, 0.0, 0.4, 1.0] {
        let all = legendre_p_all(32, x).unwrap();
        for (n, &value) in all.iter().enumerate() {
            assert!((value - eval_legendre(n as i32, x)).abs() < 1e-13);
        }
        let table = assoc_legendre_p_all(10, 5, x).unwrap();
        for (n, row) in table.iter().enumerate() {
            for (column, &value) in row.iter().enumerate() {
                let order = if column <= 5 {
                    column as i32
                } else {
                    column as i32 - 11
                };
                let scalar = assoc_legendre_p(n as i32, order, x).unwrap();
                assert!(
                    (value - scalar).abs() < 2e-10 * (1.0 + scalar.abs()),
                    "n={n},m={order},x={x}"
                );
            }
        }
    }
}

#[test]
fn rejects_out_of_domain_inputs_and_degrees() {
    assert!(legendre(257, false).is_err());
    assert!(roots_legendre(0).is_err());
    assert!(roots_legendre(1025).is_err());
    assert!(roots_jacobi(3, -1.0, 0.0).is_err());
    assert!(roots_gegenbauer(3, -0.5).is_err());
    assert!(sh_jacobi(3, 0.3, 2.0, false).is_err());
    assert!(assoc_legendre_p_all(129, 1, 0.5).is_err());
    assert!(sph_harm_y_all(3, 3, 0.3, f64::NAN).is_err());
    assert!(eval_legendre(-1, 0.5_f64).is_nan());
    assert!(eval_legendre(1_000_001, 0.5_f64).is_nan());
    assert!(eval_legendre(4097, 0.5_f64).is_finite());
    assert!(eval_jacobi(2, -1.0_f64, 0.2, 0.4).is_nan());
    assert!(eval_chebyt(2, f64::NAN).is_nan());
    let signed_degree: i32 = 3;
    assert!(assoc_legendre_p(signed_degree, 1, 0.5_f64).is_ok());
    assert!(sph_legendre_p(signed_degree, -1, 0.5_f64).is_ok());
    assert!(sph_harm_y(signed_degree, 1, 0.5_f64, 0.3).is_ok());
    for invalid_degree in [-1, i32::MIN, 1_000_001, i32::MAX] {
        assert!(matches!(
            assoc_legendre_p(invalid_degree, 1, 0.5_f64),
            Err(Error::InvalidInput(_))
        ));
        assert!(matches!(
            sph_legendre_p(invalid_degree, -1, 0.5_f64),
            Err(Error::InvalidInput(_))
        ));
        assert!(matches!(
            sph_harm_y(invalid_degree, 1, 0.5_f64, 0.3),
            Err(Error::InvalidInput(_))
        ));
    }
    assert!(assoc_legendre_p(2, 1, 2.0_f64).is_err());
    assert!(sph_legendre_p(2, 1, -0.1_f64).is_err());
    let converted: f32 = eval_legendre(3, 0.3_f32);
    assert!((converted as f64 - eval_legendre(3, 0.3_f32 as f64)).abs() < 2e-7);
}

#[test]
fn spherical_harmonics_match_condon_shortley_phase_and_table_layout() {
    for theta in [0.0, 0.25, 1.0, 2.5, std::f64::consts::PI] {
        for phi in [-2.0, -0.3, 0.0, 1.4] {
            let result = sph_harm_y(1, 1, theta, phi).unwrap();
            let amplitude = -(3.0 / (8.0 * std::f64::consts::PI)).sqrt() * theta.sin();
            assert!((result.re - amplitude * phi.cos()).abs() < 2e-13);
            assert!((result.im - amplitude * phi.sin()).abs() < 2e-13);
            let table = sph_harm_y_all(4, 3, theta, phi).unwrap();
            for (degree, row) in table.iter().enumerate() {
                for (index, &value) in row.iter().enumerate() {
                    let order = if index <= 3 {
                        index as i32
                    } else {
                        index as i32 - 7
                    };
                    let scalar = sph_harm_y(degree as i32, order, theta, phi).unwrap();
                    assert!((value.re - scalar.re).abs() < 3e-12 * (1.0 + scalar.re.abs()));
                    assert!((value.im - scalar.im).abs() < 3e-12 * (1.0 + scalar.im.abs()));
                }
            }
        }
    }
}
